'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var incrmcovariance = require( '@stdlib/stats/incr/mcovariance' );


// MAIN //

/**
* Returns an accumulator function which incrementally computes a moving unbiased sample covariance, ignoring `NaN` values.
*
* @param {PositiveInteger} W - window size
* @param {number} [meanx] - mean value
* @param {number} [meany] - mean value
* @throws {TypeError} first argument must be a positive integer
* @throws {TypeError} second argument must be a number
* @throws {TypeError} third argument must be a number
* @returns {Function} accumulator function
*
* @example
* var accumulator = incrnanmcovariance( 3 );
*
* var v = accumulator();
* // returns null
*
* v = accumulator( 2.0, 1.0 );
* // returns 0.0
*
* v = accumulator( NaN, 1.0 );
* // returns 0.0
*
* v = accumulator( -5.0, 3.14 );
* // returns ~-7.49
*
* v = accumulator( 3.0, -1.0 );
* // returns -8.35
*
* v = accumulator( 5.0, -9.5 );
* // returns -29.42
*
* v = accumulator();
* // returns -29.42
*
* @example
* var accumulator = incrnanmcovariance( 3, -2.0, 10.0 );
*/
function incrnanmcovariance( W, meanx, meany ) {
	var acc;
	if ( arguments.length > 1 ) {
		acc = incrmcovariance( W, meanx, meany );
	} else {
		acc = incrmcovariance( W );
	}
	return accumulator;

	/**
	* If provided a value, the accumulator function returns an updated unbiased sample covariance. If not provided a value, the accumulator function returns the current unbiased sample covariance.
	*
	* @private
	* @param {number} [x] - input value
	* @param {number} [y] - input value
	* @returns {(number|null)} unbiased sample covariance or null
	*/
	function accumulator( x, y ) {
		if ( arguments.length === 0 || isnan( x ) || isnan( y ) ) {
			return acc();
		}
		return acc( x, y );
	}
}


// EXPORTS //

module.exports = incrnanmcovariance;
